package com.ibm.advocacy.service;

import com.ibm.advocacy.collector.SharePointCollector;
import com.ibm.advocacy.model.*;
import com.ibm.advocacy.storage.RuntimeWorkspace;
import io.quarkus.test.junit.QuarkusTest;
import jakarta.inject.Inject;
import jakarta.ws.rs.BadRequestException;
import jakarta.ws.rs.ClientErrorException;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.junit.jupiter.api.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.ibm.advocacy.model.MetricsSchema.*;

@QuarkusTest
class WorkbookPublicationTest {
    @Inject RunService runs;
    @Inject WorkbookPublicationService publications;
    @Inject RuntimeWorkspace workspace;
    @Inject SharePointCollector collector;
    String url="https://ibm.sharepoint.com/sites/DEPT-DeveloperRelations/Shared%20Documents/Publication%20test.xlsx";
    @BeforeEach void setup() throws Exception {for(String name:List.of("RUN.md","AGENTS.md"))workspace.bytes(workspace.path(name),Files.readAllBytes(Path.of("runtimes",name)));FakeSharePointCollector.files.clear();FakeSharePointCollector.denyWrites=false;}
    @AfterEach void cleanup(){FakeSharePointCollector.files.clear();FakeSharePointCollector.denyWrites=false;}
    static void row(org.apache.poi.ss.usermodel.Sheet sheet,int index,String... values){var row=sheet.createRow(index);for(int i=0;i<values.length;i++)row.createCell(i).setCellValue(values[i]);}
    byte[] current(boolean pending) throws Exception {try(XSSFWorkbook book=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){var sheet=book.createSheet("Current month inputs");row(sheet,0,"Date","Author","Tool","Name of activity","Type of activity",VIEWS,"Duration (in hours)",URL);row(sheet,1,"2026-09-20","Daniel Oh;Kevin Dubois","IBM Runtimes","Shared attendance","Standard participation","15","1","");if(pending)row(sheet,2,"2026-09-20","Daniel Oh","IBM Bob","Pending other activity","Analyst or press briefing","5","1","");book.write(out);return out.toByteArray();}}
    byte[] history() throws Exception {try(XSSFWorkbook book=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){var sheet=book.createSheet("August inputs");row(sheet,0,"Date","Author","Tool","Name of activity","Type of activity",VIEWS,"Current total","Previous total","Trailing 90-day",URL);row(sheet,1,"2026-08-10","A","IBM Bob","Historical video","Recorded video","50","100","0","Yes","");var model=book.createSheet("DA metric model 2026");row(model,0,"Activities","Unit Measure","Weight","Trailing 90 days?");row(model,1,"Standard participation","number of standards","100","No");row(model,2,"Recorded video","Views","0.5","Yes");row(model,3,"Analyst or press briefing","Activities","1","No");book.write(out);return out.toByteArray();}}
    Run await(String id,String status) throws Exception {for(int i=0;i<600;i++){Run run=runs.get(id);if(run.status.equals(status))return run;if(run.status.equals("FAILED_RETRYABLE"))fail(run.error);Thread.sleep(20);}throw new AssertionError("Timed out waiting for "+status);}
    void approve(Run run) throws Exception {runs.approve(run.id,run.phase,run.version,RunService.digest(run),false);}
    Run checkpoint() throws Exception {return checkpoint(false);}
    Run checkpoint(boolean pending) throws Exception {byte[] history=history();FakeSharePointCollector.files.put(collector.fileUri(url).toASCIIString(),history);Run run=runs.createSharePointWorkbooks(current(pending),"AvocadoBot.xlsx",history,"Metrics.xlsx","2026-09","Current month inputs",List.of("August inputs"),"https://ibm-my.sharepoint.com/personal/test/Documents/AvocadoBot.xlsx",url);runs.start(run.id,true);for(int phase=1;phase<=3;phase++){Run ready=await(run.id,"AWAITING_APPROVAL");assertEquals(phase,ready.phase);approve(ready);}return await(run.id,"AWAITING_PUBLICATION");}
    @Test void humanReviewedPublicationGatesTrailingAndPreservesImmutableBaselinesThenPublishesCompleteSnapshot() throws Exception {
        Run run=checkpoint();assertFalse(Files.exists(workspace.runPath(run.id,"state/phase-4-updated_90-day.json")));byte[] original=Files.readAllBytes(workspace.runPath(run.id,"rawdata/trailing-original.xlsx"));int writes=FakeSharePointCollector.writes.get();
        var plan=publications.preview(run.id,run.version,run.reportingRevision);assertEquals(0,FakeSharePointCollector.writes.get()-writes);assertTrue(plan.publication().createdSheet);assertEquals(3,plan.publication().appended);assertTrue(plan.rows().stream().anyMatch(row->row.get(VIEWS).equals("0.5")));assertThrows(BadRequestException.class,()->publications.publish(run.id,run.version,0,plan.publication().planDigest,false));assertThrows(ClientErrorException.class,()->publications.publish(run.id,run.version,0,"stale",true));
        publications.publish(run.id,run.version,0,plan.publication().planDigest,true);Run trailing=await(run.id,"AWAITING_APPROVAL");assertEquals(4,trailing.phase);assertEquals("CURRENT_INPUTS",trailing.publication.stage);assertEquals("100",workspace.data(run.id,"trailing-source").rows.getFirst().get("Current total"));assertArrayEquals(original,Files.readAllBytes(workspace.runPath(run.id,"rawdata/trailing-original.xlsx")));assertEquals(1,FakeSharePointCollector.writes.get()-writes);approve(trailing);
        Run complete=await(run.id,"COMPLETED");var finalPlan=publications.preview(run.id,complete.version,complete.reportingRevision);assertEquals("COMPLETED",finalPlan.publication().stage);assertEquals(0,finalPlan.publication().appended);publications.publish(run.id,complete.version,complete.reportingRevision,finalPlan.publication().planDigest,true);Run saved=await(run.id,"COMPLETED");assertEquals("COMPLETED",saved.publication.stage);assertEquals("PUBLISHED",saved.publication.status);assertEquals("100",runs.report(run.id,"combined").impact());
        try(XSSFWorkbook book=new XSSFWorkbook(new ByteArrayInputStream(FakeSharePointCollector.files.get(collector.fileUri(url).toASCIIString())))){assertEquals(3,book.getSheet("September 2026 inputs").getLastRowNum());assertNotNull(book.getSheet("August inputs"));assertNotNull(book.getSheet("DA metric model 2026"));}
    }
    @Test void remoteChangeStopsPublicationAndDoesNotStartTrailingUntilAFreshPreview() throws Exception {Run run=checkpoint();var plan=publications.preview(run.id,run.version,0);byte[] changed;try(XSSFWorkbook book=new XSSFWorkbook(new ByteArrayInputStream(history()));ByteArrayOutputStream out=new ByteArrayOutputStream()){book.createSheet("Other person's edit").createRow(0).createCell(0).setCellValue("Keep me");book.write(out);changed=out.toByteArray();}FakeSharePointCollector.files.put(collector.fileUri(url).toASCIIString(),changed);publications.publish(run.id,run.version,0,plan.publication().planDigest,true);Run failed=await(run.id,"AWAITING_PUBLICATION");assertEquals("FAILED",failed.publication.status);assertArrayEquals(changed,FakeSharePointCollector.files.get(collector.fileUri(url).toASCIIString()));assertFalse(failed.artifacts.containsKey("updated_90-day.csv"));assertFalse(failed.error.isBlank());var refreshed=publications.preview(run.id,run.version,0);assertEquals("",runs.get(run.id).error);assertEquals("PREVIEW_READY",runs.get(run.id).publication.status);publications.publish(run.id,run.version,0,refreshed.publication().planDigest,true);assertEquals(4,await(run.id,"AWAITING_APPROVAL").phase);}
    @Test void deniedEditAccessKeepsTheCheckpointRetryableAndPreviewRejectsStaleResults() throws Exception {Run run=checkpoint();assertThrows(ClientErrorException.class,()->publications.preview(run.id,run.version+1,0));var plan=publications.preview(run.id,run.version,0);FakeSharePointCollector.denyWrites=true;publications.publish(run.id,run.version,0,plan.publication().planDigest,true);Run failed=await(run.id,"AWAITING_PUBLICATION");assertEquals("FAILED",failed.publication.status);assertTrue(failed.error.contains("denied"));assertEquals(3,failed.phase);}
    @Test void interruptedPublicationReturnsToReviewWithoutLosingThePlan() throws Exception {Run run=checkpoint();var plan=publications.preview(run.id,run.version,0);run=runs.get(run.id);run.status="PUBLISHING_WORKBOOK";run.publication.status="PUBLISHING";workspace.save(run);Run recovered=runs.get(run.id);assertEquals("AWAITING_PUBLICATION",recovered.status);assertEquals("FAILED",recovered.publication.status);assertEquals(plan.publication().planDigest,recovered.publication.planDigest);assertTrue(recovered.error.contains("interrupted"));}    @Test void unresolvedReportingCannotBeMarkedCompletedAndAConfirmedCorrectionAllowsFinalPublication() throws Exception {
        Run run=checkpoint(true);var plan=publications.preview(run.id,run.version,0);assertEquals(1,plan.publication().skipped);publications.publish(run.id,run.version,0,plan.publication().planDigest,true);approve(await(run.id,"AWAITING_APPROVAL"));Run complete=await(run.id,"COMPLETED");assertThrows(BadRequestException.class,()->publications.preview(run.id,complete.version,0));var report=runs.report(run.id,"combined");var missing=report.details().rows.stream().filter(row->row.get("Reporting handling").equals("Needs attention")).findFirst().orElseThrow();runs.confirmMonthEnd(run.id,0,"current",missing.id,"5","2026-09-30","Verified other metric");Run corrected=runs.get(run.id);var finalPlan=publications.preview(run.id,corrected.version,corrected.reportingRevision);publications.publish(run.id,corrected.version,corrected.reportingRevision,finalPlan.publication().planDigest,true);assertEquals("COMPLETED",await(run.id,"COMPLETED").publication.stage);assertEquals("105",runs.report(run.id,"combined").impact());
    }
    @Test void statusEndpointIsReadOnlyAndDoesNotAdvancePublicationOrErasePastFailure() throws Exception {
        Run run=checkpoint();run.error="Previous failure";workspace.save(run);int writes=FakeSharePointCollector.writes.get();
        io.restassured.RestAssured.given().get("/api/runs/"+run.id+"/publication/status").then().statusCode(200).body("checkoutType",org.hamcrest.Matchers.equalTo(2)).body("lockOwnerReported",org.hamcrest.Matchers.equalTo(true));
        Run after=runs.get(run.id);assertEquals("AWAITING_PUBLICATION",after.status);assertEquals(run.version,after.version);assertEquals("Previous failure",after.error);assertEquals(writes,FakeSharePointCollector.writes.get());assertFalse(after.artifacts.containsKey("updated_90-day.csv"));
    }
    @Test void completedAgentRunDuringOctoberPublishesProvisionalCurrentAndTrailingSnapshot() throws Exception {
        byte[] currentBytes;try(XSSFWorkbook book=new XSSFWorkbook(new ByteArrayInputStream(current(false)));ByteArrayOutputStream out=new ByteArrayOutputStream()){book.getSheet("Current month inputs").getRow(1).getCell(0).setCellValue("2026-10-05");book.write(out);currentBytes=out.toByteArray();}
        byte[] historical=history();FakeSharePointCollector.files.put(collector.fileUri(url).toASCIIString(),historical);
        Run run=runs.createSharePointWorkbooks(currentBytes,"AvocadoBot.xlsx",historical,"Metrics.xlsx","2026-10","Current month inputs",List.of("August inputs"),"https://ibm-my.sharepoint.com/personal/test/Documents/AvocadoBot.xlsx",url);run.workbook.put("asOf","2026-10-13");run.workbook.put("snapshotStage","PROVISIONAL");workspace.save(run);
        runs.start(run.id,true);for(int phase=1;phase<=3;phase++){Run ready=await(run.id,"AWAITING_APPROVAL");assertEquals(phase,ready.phase);approve(ready);}run=await(run.id,"AWAITING_PUBLICATION");
        var currentPlan=publications.preview(run.id,run.version,run.reportingRevision);assertEquals("CURRENT_INPUTS",currentPlan.publication().stage);assertTrue(currentPlan.publication().createdSheet);assertTrue(currentPlan.rows().stream().anyMatch(row->row.get("Contribution").equals("Current")));assertTrue(currentPlan.rows().stream().allMatch(row->row.get("Snapshot as of").equals("2026-10-13")));
        publications.publish(run.id,run.version,run.reportingRevision,currentPlan.publication().planDigest,true);approve(await(run.id,"AWAITING_APPROVAL"));Run complete=await(run.id,"COMPLETED");
        var plan=publications.preview(run.id,complete.version,complete.reportingRevision);assertEquals("PROVISIONAL",plan.publication().stage);assertTrue(plan.rows().stream().anyMatch(row->row.get("Contribution").equals("Current")));assertTrue(runs.report(run.id,"combined").provisional());
        publications.publish(run.id,complete.version,complete.reportingRevision,plan.publication().planDigest,true);Run saved=await(run.id,"COMPLETED");assertEquals("PUBLISHED",saved.publication.status);assertEquals("PROVISIONAL",saved.publication.stage);assertTrue(saved.publication.message.contains("Provisional snapshot published"));
        byte[] workbook=FakeSharePointCollector.files.get(collector.fileUri(url).toASCIIString());assertThrows(BadRequestException.class,()->new WorkbookService().historySheets(workbook,"2026-11"));
    }
    @Test void freshTrailingGrowthReplacesCarriedSnapshotAndPreservesStartingBaselineForReruns() throws Exception {
        byte[] historical;try(XSSFWorkbook book=new XSSFWorkbook(new ByteArrayInputStream(history()));ByteArrayOutputStream out=new ByteArrayOutputStream()){
            var sheet=book.getSheet("August inputs");sheet.getRow(0).createCell(10).setCellValue("Snapshot stage");sheet.getRow(1).createCell(10).setCellValue("BASELINE_CARRY");book.write(out);historical=out.toByteArray();
        }
        FakeSharePointCollector.files.put(collector.fileUri(url).toASCIIString(),historical);
        Run run=runs.createSharePointWorkbooks(current(false),"AvocadoBot.xlsx",historical,"Metrics.xlsx","2026-09","Current month inputs",List.of("August inputs"),"https://ibm-my.sharepoint.com/personal/test/Documents/AvocadoBot.xlsx",url);
        assertEquals("BASELINE_CARRY",workspace.data(run.id,"trailing-source").rows.getFirst().get("Snapshot stage"));
        runs.start(run.id,true);for(int phase=1;phase<=3;phase++){Run ready=await(run.id,"AWAITING_APPROVAL");approve(ready);}run=await(run.id,"AWAITING_PUBLICATION");
        var partial=publications.preview(run.id,run.version,run.reportingRevision);publications.publish(run.id,run.version,run.reportingRevision,partial.publication().planDigest,true);approve(await(run.id,"AWAITING_APPROVAL"));Run complete=await(run.id,"COMPLETED");
        // Offline deterministic Phase 4 result: the inherited carry marker must not suppress fresh growth.
        Row measured=workspace.data(run.id,"trailing-source").rows.getFirst().copy();measured.cells.put("Current total","180");measured.cells.put("Previous total","100");measured.cells.put(VIEWS,"80");measured.cells.put("Metric basis","Trailing delta");measured.cells.put("Measured at","2026-09-30T12:00:00Z");
        Artifact artifact=complete.artifacts.get("updated_90-day.csv");workspace.bytes(workspace.runPath(run.id,"output/"+artifact.version()+"/updated_90-day.json"),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsBytes(Data.output(new Data(),List.of(measured))));
        assertEquals("140",runs.report(run.id,"combined").impact());
        var finalPlan=publications.preview(run.id,complete.version,complete.reportingRevision);Row fresh=finalPlan.rows().stream().filter(row->row.get("Name of activity").equals("Historical video")).findFirst().orElseThrow();assertEquals("180",fresh.get("Current total"));assertEquals("100",fresh.get("Starting baseline"));assertEquals("COMPLETED",fresh.get("Snapshot stage"));
        publications.publish(run.id,complete.version,complete.reportingRevision,finalPlan.publication().planDigest,true);await(run.id,"COMPLETED");byte[] published=FakeSharePointCollector.files.get(collector.fileUri(url).toASCIIString());
        try(XSSFWorkbook book=new XSSFWorkbook(new ByteArrayInputStream(published))){var sheet=book.getSheet("September 2026 inputs");var fields=MonthlyInputWorkbook.columns(sheet.getRow(0),new org.apache.poi.ss.usermodel.DataFormatter());var old=sheet.getRow(3);assertEquals(180,old.getCell(fields.get("Current total")).getNumericCellValue());assertEquals(100,old.getCell(fields.get("Starting baseline")).getNumericCellValue());}
        WorkbookService reader=new WorkbookService();reader.blogs=new BlogSheetReader();var same=reader.prepare(new WorkbookRequest(current(false),"2026-09","Current month inputs",List.of("September 2026 inputs"),published),java.time.LocalDate.of(2026,9,30));assertEquals("100",same.trailing().rows.getFirst().get("Current total"));
        byte[] october;try(XSSFWorkbook book=new XSSFWorkbook(new ByteArrayInputStream(current(false)));ByteArrayOutputStream out=new ByteArrayOutputStream()){book.getSheet("Current month inputs").getRow(1).getCell(0).setCellValue("2026-10-02");book.write(out);october=out.toByteArray();}
        var next=reader.prepare(new WorkbookRequest(october,"2026-10","Current month inputs",List.of("September 2026 inputs"),published),java.time.LocalDate.of(2026,10,13));assertEquals("180",next.trailing().rows.getFirst().get("Current total"));
    }

}
